using System;
using System.Collections.Generic;
using System.IO;
using CosmicBlock.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
public static class BestScoreReadabilityProbe {
 static double start;static int frames,count;static string errors="",warnings="";static readonly List<string> results=new List<string>();
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/Game.unity");start=EditorApplication.timeSinceStartup;Application.logMessageReceived+=Log;EditorApplication.update+=Check;EditorApplication.EnterPlaymode();}
 static void Check(){if(EditorApplication.timeSinceStartup-start>180){Finish(false,"timeout");return;}if(!EditorApplication.isPlaying||++frames<45)return;EditorApplication.update-=Check;try{var flow=UnityEngine.Object.FindAnyObjectByType<GameFlowController>();flow.Play();foreach(int h in new[]{1920,2400,1440})foreach(int value in new[]{15930,99999,999999}){Capture(h,value,true);Capture(h,value,false);}Finish(errors.Length==0,errors);}catch(Exception e){Finish(false,e.ToString());}}
 static void Capture(int h,int value,bool before){var canvas=GameObject.Find("GameCanvas").GetComponent<Canvas>();var cam=Camera.main;var safe=(RectTransform)canvas.transform.Find("SafeArea");var sa=safe.GetComponent<SafeArea>();var visual=UnityEngine.Object.FindAnyObjectByType<GameVisualPresentation>();var best=visual.BestText;var frame=(RectTransform)visual.transform.Find("BestFrameArea");var originalMode=canvas.renderMode;var originalCamera=canvas.worldCamera;var originalTarget=cam.targetTexture;var originalActive=RenderTexture.active;bool enabled=sa.enabled,ortho=cam.orthographic;float size=cam.orthographicSize;var amin=safe.anchorMin;var amax=safe.anchorMax;var omin=safe.offsetMin;var omax=safe.offsetMax;var rt=new RenderTexture(1080,h,24);Texture2D tex=null;
 try{sa.enabled=false;rt.Create();cam.targetTexture=rt;cam.orthographic=true;cam.orthographicSize=h/2f;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=10;safe.anchorMin=h==2400?new Vector2(.02f,.04f):Vector2.zero;safe.anchorMax=h==2400?new Vector2(.98f,.94f):Vector2.one;safe.offsetMin=safe.offsetMax=Vector2.zero;Canvas.ForceUpdateCanvases();visual.RefreshVisual();Canvas.ForceUpdateCanvases();float q=Mathf.Min(safe.rect.width/1080f,safe.rect.height/1920f);
 if(before){visual.ScoreText.rectTransform.anchoredPosition=new Vector2(0,safe.rect.height/2-145*q);frame.sizeDelta=new Vector2(412.5f,137.5f)*q;frame.anchoredPosition=new Vector2(safe.rect.width/2-206.25f*q,safe.rect.height/2-68.75f*q);best.rectTransform.anchorMin=new Vector2(.4f,.17f);best.rectTransform.anchorMax=new Vector2(.9f,.59f);best.margin=Vector4.one*q;}
 visual.RenderValues(value,value);Canvas.ForceUpdateCanvases();best.ForceMeshUpdate(true,true);visual.ScoreText.ForceMeshUpdate(true,true);var glyph=GlyphBounds(best);var scoreGlyph=GlyphBounds(visual.ScoreText);var label=GlyphBounds(visual.transform.Find("ScoreLabel").GetComponent<TMP_Text>());
 if(!before){var bounds=World(safe);Req(bounds.Contains(World(frame).min)&&bounds.Contains(World(frame).max),"Safe Area "+h);Req(!glyph.Overlaps(scoreGlyph)&&!glyph.Overlaps(label),"BEST and central SCORE glyphs separated "+h+" "+value);Req(!best.isTextOverflowing&&!best.isTextTruncated,"no truncation "+value);var rect=World(best.rectTransform);Req(rect.Contains(glyph.min)&&rect.Contains(glyph.max),"all BEST glyphs inside padded rect");Req(Mathf.Abs(frame.rect.width/frame.rect.height-3)<.001f,"original frame aspect");Req(best.fontSizeMax==53.65f,"font ceiling preserved");}
 results.Add((before?"BEFORE":"AFTER")+" h="+h+" value="+value+" font="+best.fontSize+" glyph="+glyph+" gap="+(glyph.xMin-scoreGlyph.xMax)+" frame="+frame.rect.size);
 var bg=safe.Find("Background");bg?.GetComponent<AspectFillBackground>()?.SendMessage("LateUpdate");cam.Render();RenderTexture.active=rt;tex=new Texture2D(1080,h,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1080,h),0,0);tex.Apply();File.WriteAllBytes("Validation/best_panel_"+(before?"before":"after")+"_"+h+"_"+value+".png",tex.EncodeToPNG());
 }finally{canvas.renderMode=originalMode;canvas.worldCamera=originalCamera;cam.targetTexture=originalTarget;cam.orthographic=ortho;cam.orthographicSize=size;RenderTexture.active=originalActive;safe.anchorMin=amin;safe.anchorMax=amax;safe.offsetMin=omin;safe.offsetMax=omax;sa.enabled=enabled;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);visual.RefreshVisual();}}
 static Rect GlyphBounds(TMP_Text t){t.ForceMeshUpdate(true,true);Vector2 min=new Vector2(float.MaxValue,float.MaxValue),max=new Vector2(float.MinValue,float.MinValue);for(int i=0;i<t.textInfo.characterCount;i++){var c=t.textInfo.characterInfo[i];if(!c.isVisible)continue;var a=t.transform.TransformPoint(c.bottomLeft);var b=t.transform.TransformPoint(c.topRight);min=Vector2.Min(min,a);max=Vector2.Max(max,b);}return Rect.MinMaxRect(min.x,min.y,max.x,max.y);}
 static Rect World(RectTransform r){var a=new Vector3[4];r.GetWorldCorners(a);return Rect.MinMaxRect(a[0].x,a[0].y,a[2].x,a[2].y);}
 static void Req(bool v,string m){count++;if(!v)throw new Exception(m);}
 static void Log(string m,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)errors+=m+"\n";if(type==LogType.Warning)warnings+=m+"\n";}
 static void Finish(bool pass,string why){EditorApplication.update-=Check;Application.logMessageReceived-=Log;File.WriteAllText("Validation/best_panel_results.txt",string.Join("\n",results)+"\nAssertions="+count+"\nWarnings="+warnings+"\n"+(pass?"BEST_PANEL_PASS":why));EditorApplication.Exit(pass?0:1);}
}
